JS = r'''
document.querySelectorAll('[data-series]').forEach(b => b.addEventListener('click', () => {
  const on = b.getAttribute('aria-pressed') !== 'true';
  b.setAttribute('aria-pressed', String(on));
  const scope = b.closest('.rp-c');
  scope.querySelector(`[data-series-line="${b.dataset.series}"]`)?.toggleAttribute('visibility', !on);
  const line = scope.querySelector(`[data-series-line="${b.dataset.series}"]`);
  if (line) line.style.display = on ? '' : 'none';
}));
'''
